insert into herramienta values ('I-01', 'Identificar', 'Fing – Network Scanner', 'ambos', 'https://play.google.com/store/apps/details?id=com.overlook.android.fing', 'fing.com', 'Gratis con funciones de pago opcionales', true, 4, 'Escanea la red Wi-Fi y lista cada dispositivo conectado con su IP, fabricante y modelo. El propietario confirma desde su celular que solo los equipos del negocio usan el Wi-Fi del local.', 'ID.AM-01', 'Primera opción (inventario desde el celular)') on conflict (id) do nothing;
insert into herramienta values ('I-05', 'Identificar', 'Revisión de contraseñas de Google (Password Checkup)', 'ambos', 'https://passwords.google.com/checkup', 'google.com', 'Gratis', true, 5, 'Revisa las contraseñas guardadas en la cuenta de Google y marca las filtradas, repetidas o débiles.', 'ID.RA-01', 'Primera opción (contraseñas filtradas)') on conflict (id) do nothing;
insert into herramienta values ('I-04', 'Identificar', 'Have I Been Pwned', 'ambos', 'https://haveibeenpwned.com/', 'haveibeenpwned.com', 'Gratis', false, 3, 'Compara el correo con filtraciones públicas e indica en cuáles aparece.', 'ID.RA-01', 'Complementaria (correos filtrados fuera de Google)') on conflict (id) do nothing;
insert into herramienta values ('I-16', 'Identificar', 'Google – Estado del sitio (Navegación segura)', 'ambos', 'https://transparencyreport.google.com/safe-browsing/search', 'google.com', 'Gratis', true, 4, 'Revisa con la tecnología de Navegación segura de Google si una página es peligrosa, sin necesidad de abrirla. El propietario pega el enlace sospechoso que le llegó por WhatsApp o SMS y ve el resultado.', 'ID.RA-03 (amenazas identificadas)', 'Primera opción (revisar enlaces)') on conflict (id) do nothing;
insert into herramienta values ('I-15', 'Identificar', 'VirusTotal', 'ambos', 'https://www.virustotal.com/', 'virustotal.com', 'Gratis', false, 3, 'Analiza un enlace o un archivo con más de 70 motores antivirus y servicios de reputación antes de abrirlo. Complementa a I-16, que solo revisa páginas: sirve para revisar un comprobante, factura o APK que llegó por correo o WhatsApp.', 'ID.RA-03 (amenazas identificadas)', 'Complementaria (archivos sospechosos)') on conflict (id) do nothing;
insert into herramienta values ('I-07', 'Identificar', 'Find Hub de Google (antes «Encontrar mi dispositivo»)', 'celular', 'https://play.google.com/store/apps/details?id=com.google.android.apps.adm', 'google.com', 'Gratis', true, 5, 'Lista los dispositivos Android ligados a la cuenta y su última ubicación.', 'ID.AM-01', 'Primera opción (celulares Android)') on conflict (id) do nothing;
insert into herramienta values ('I-08', 'Identificar', 'Buscar de Apple (Find My)', 'celular', 'https://www.icloud.com/find', 'icloud.com', 'Gratis', true, 5, 'Equivalente a I-07 para negocios que operan con iPhone o iPad.', 'ID.AM-01', 'Primera opción (iPhone)') on conflict (id) do nothing;
insert into herramienta values ('I-06', 'Identificar', 'Revisión de seguridad de Google (Security Checkup)', 'ambos', 'https://myaccount.google.com/security-checkup', 'google.com', 'Gratis', true, 5, 'Muestra los dispositivos con sesión abierta, las apps con acceso a la cuenta y los datos de recuperación. Permite detectar un celular viejo o de un exempleado que todavía entra al Gmail del negocio.', 'ID.AM-01, ID.AM-02', 'Primera opción (accesos a la cuenta)') on conflict (id) do nothing;
insert into herramienta values ('I-09', 'Identificar', 'WhatsApp – Dispositivos vinculados', 'celular', 'https://faq.whatsapp.com/483137970953208?lang=es', 'whatsapp.com', 'Gratis', true, 5, 'Lista los computadores y navegadores con WhatsApp Web abierto y permite cerrar los que no se reconocen.', 'ID.AM-01', 'Primera opción (sesiones de WhatsApp)') on conflict (id) do nothing;
insert into herramienta values ('I-11', 'Identificar', 'Seguridad de Windows – Estado de protección', 'pc', 'https://support.microsoft.com/windows/security/windows-security/windows-security-app-overview', 'microsoft.com', 'Gratis', true, 5, 'Reúne en una pantalla el estado del antivirus, el firewall, las actualizaciones y la seguridad del dispositivo, con indicadores de color. Identifica qué protección falta antes de activarla con las herramientas de Proteger.', 'ID.RA-01', 'Primera opción (estado del computador)') on conflict (id) do nothing;
insert into herramienta values ('P-01', 'Proteger', 'Microsoft Defender Antivirus', 'pc', 'https://support.microsoft.com/windows/security/windows-security/windows-security-app-overview', 'microsoft.com', 'Gratis', true, 5, 'Bloquea la ejecución de archivos maliciosos y se actualiza con Windows Update. «Acceso controlado a carpetas» defiende contra ransomware. AV-TEST jul–ago 2026: 17,5 de 18 y TOP PRODUCT.', 'PR.PS-05 (NIST SP 1300 lo asocia a DE.CM-09; ver comentario)', 'Primera opción (antivirus)') on conflict (id) do nothing;
insert into herramienta values ('P-02', 'Proteger', 'Avast Free Antivirus', 'pc', 'https://www.avast.com/es-mx/lp-free-av', 'avast.com', 'Gratis (versión de pago opcional)', true, 4, 'Antivirus gratuito para instalar, con protección en tiempo real, bloqueo de enlaces peligrosos, protección contra ransomware y revisión de la red Wi-Fi. 18 de 18 puntos y TOP PRODUCT en AV-TEST (julio–agosto 2026). Al instalarlo, Windows desactiva la protección en tiempo real de Defender, porque no deben funcionar dos antivirus a la vez. Conviene revisar sus opciones de privacidad.', 'PR.PS-05', 'Antivirus para instalar en el computador') on conflict (id) do nothing;
insert into herramienta values ('P-20', 'Proteger', 'Google Play Protect', 'celular', 'https://support.google.com/googleplay/answer/2812853?hl=es', 'google.com', 'Gratis', true, 5, 'Revisa las apps instaladas y las que se descargan, y avisa o desactiva las dañinas. En la prueba de AV-TEST de julio de 2026 obtuvo 6 de 6 en protección, rendimiento y usabilidad. Protege el celular con el que se cobra por Nequi.', 'PR.PS-05', 'Primera opción (antivirus del celular)') on conflict (id) do nothing;
insert into herramienta values ('P-21', 'Proteger', 'Avast Antivirus & Security (Android; en Google Play: «Avast One Antivirus, Seguridad»)', 'celular', 'https://play.google.com/store/apps/details?id=com.avast.android.mobilesecurity', 'avast.com', 'Gratis con funciones de pago opcionales', true, 4, 'App antivirus para Android; 6/6/6 en AV-TEST (julio 2026). Añade funciones con ofertas de la versión de pago.', 'PR.PS-05', 'Antivirus para instalar en el celular') on conflict (id) do nothing;
insert into herramienta values ('P-23', 'Proteger', 'Navegación segura mejorada de Google', 'ambos', 'https://myaccount.google.com/security', 'google.com', 'Gratis', true, 5, 'Avisa o bloquea páginas, descargas y extensiones peligrosas en Chrome, Gmail y Google Chat, y alerta si una contraseña aparece en una filtración. Se activa una vez y protege todos los equipos con la misma cuenta.', 'PR.PS-05; PR.AT-01', 'Primera opción (navegación segura)') on conflict (id) do nothing;
insert into herramienta values ('P-24', 'Proteger', 'WOT: Website Security & Safety Checker', 'pc', 'https://chromewebstore.google.com/detail/wot-website-security-safe/bhmmomiinigofkjcapegjjndpbikblnp?hl=es-419&utm_source=ext_sidebar', 'mywot.com', 'Gratis (ofrece compras dentro de la aplicación)', true, 4, 'Extensión que muestra la reputación de seguridad de los sitios en los resultados de búsqueda y avisa o bloquea páginas de phishing, estafa o dañinas antes de abrirlas. Sirve en el computador del negocio aunque no se use cuenta de Google. Requiere crear una cuenta gratuita de WOT y recopila historial de navegación.', 'PR.PS-05', 'Extensión para el computador del negocio') on conflict (id) do nothing;
insert into herramienta values ('P-34', 'Proteger', 'Brave (navegador con Brave Shields)', 'ambos', 'https://brave.com/', 'brave.com', 'Gratis', true, 4, 'Navegador gratuito basado en Chromium (se usa igual que Chrome) que trae activados de fábrica los escudos Brave Shields y la Navegación segura de Google: bloquea sitios de phishing y malware, descargas peligrosas, anuncios y rastreadores. El negocio lo usa como navegador del computador o del celular para abrir los enlaces que llegan por WhatsApp, sin instalar extensiones ni crear cuenta.', 'PR.PS-05', 'Navegador con protección incluida') on conflict (id) do nothing;
insert into herramienta values ('P-28', 'Proteger', 'Gestor de contraseñas de Google', 'ambos', 'https://passwords.google.com/', 'google.com', 'Gratis', true, 5, 'Guarda las contraseñas en la cuenta de Google, sugiere contraseñas fuertes, las autocompleta y avisa si están repetidas, son débiles o se filtraron. Reemplaza el cuaderno de contraseñas sin instalar nada.', 'PR.AA-01', 'Primera opción (contraseñas)') on conflict (id) do nothing;
insert into herramienta values ('P-04', 'Proteger', 'Bitwarden', 'ambos', 'https://bitwarden.com/download/', 'bitwarden.com', 'Gratis; plan de bajo costo (Teams 5 USD/usuario/mes)', true, 4, 'Bóveda cifrada de extremo a extremo; genera contraseñas fuertes y las autocompleta.', 'PR.AA-01', 'Primera opción (contraseñas)') on conflict (id) do nothing;
insert into herramienta values ('P-06', 'Proteger', 'Google Authenticator', 'celular', 'https://play.google.com/store/apps/details?id=com.google.android.apps.authenticator2', 'google.com', 'Gratis', true, 4, 'Genera códigos temporales de 6 dígitos como segundo paso al iniciar sesión y puede sincronizarlos con la cuenta de Google. Protege el correo y las redes sociales aunque se filtre la contraseña.', 'PR.AA-03', 'Primera opción (verificación en dos pasos)') on conflict (id) do nothing;
insert into herramienta values ('P-09', 'Proteger', 'WhatsApp – Verificación en dos pasos', 'celular', 'https://faq.whatsapp.com/1278661612895630/?cms_platform=android&helpref=platform_switcher&locale=es_LA', 'whatsapp.com', 'Gratis', true, 5, 'Pide un PIN de 6 dígitos cada vez que alguien intenta registrar el número en otro celular; admite correo de recuperación.', 'PR.AA-03', 'Primera opción (WhatsApp)') on conflict (id) do nothing;
insert into herramienta values ('P-18', 'Proteger', 'Nequi – Clave dinámica y botón de pánico', 'celular', 'https://www.elpais.com.co/economia/en-que-consiste-la-funcion-de-nequi-clave-dinamica-1054.html', 'nequi.com.co', 'Gratis', true, 5, 'La clave dinámica es un código de 6 dígitos que cambia cada 45 segundos, funciona sin internet y se ve en la parte superior derecha de la pantalla de inicio de Nequi o en el candado de la «mochila». El botón de pánico de la web bloquea la cuenta si roban el celular. Antes de entregar un producto, el comerciante debe confirmar el pago en Movimientos y no aceptar capturas, por el fraude de comprobantes falsos «Nequi Glitch».', 'PR.AA-03', 'Primera opción (cobros por Nequi)') on conflict (id) do nothing;
insert into herramienta values ('P-16', 'Proteger', 'Verificación en 2 pasos de Google (Gmail)', 'ambos', 'https://myaccount.google.com/security', 'google.com', 'Gratis', true, 4, 'Pide un segundo factor (código por SMS, llamada o llave de seguridad) además de la contraseña.', 'PR.AA-03', 'Primera opción (correo)') on conflict (id) do nothing;
insert into herramienta values ('P-17', 'Proteger', 'Autenticación en dos pasos de Facebook', 'ambos', 'https://www.facebook.com/settings', 'facebook.com', 'Gratis', true, 4, 'Exige un código adicional al iniciar sesión en un dispositivo nuevo.', 'PR.AA-03', 'Primera opción (redes sociales)') on conflict (id) do nothing;
insert into herramienta values ('P-30', 'Proteger', 'Teléfono de Google – Filtro de llamadas spam', 'celular', 'https://play.google.com/store/apps/details?id=com.google.android.dialer', 'google.com', 'Gratis', true, 5, 'Identifica números sospechosos con bases de datos y reportes de otros usuarios; muestra una advertencia o evita que el teléfono suene. Protege contra las llamadas de supuestos bancos o proveedores que buscan robar claves.', 'PR.AT-01; PR.PS-01', 'Primera opción (llamadas fraudulentas)') on conflict (id) do nothing;
insert into herramienta values ('P-32', 'Proteger', 'Files de Google – Carpeta segura', 'celular', 'https://play.google.com/store/apps/details?id=com.google.android.apps.nbu.files', 'google.com', 'Gratis', true, 4, 'Carpeta cifrada con PIN dentro del celular para guardar documentos, fotos y audios sensibles; se bloquea al salir de la app. Sirve para guardar fotos del RUT, facturas o datos de clientes que hoy quedan en la galería.', 'PR.DS-01', 'Primera opción (documentos en el celular)') on conflict (id) do nothing;
insert into herramienta values ('P-33', 'Proteger', 'Windows Update (actualizaciones automáticas)', 'pc', 'https://rog.asus.com/es/support/FAQ/1044671', 'microsoft.com', 'Gratis', true, 5, 'Descarga e instala las actualizaciones de seguridad de Windows; en Windows 11 se aplican de forma automática y solo pueden pausarse por un tiempo. El propietario solo revisa que no haya actualizaciones pendientes y reinicia cuando se lo pide.', 'PR.PS-02', 'Primera opción (actualizaciones)') on conflict (id) do nothing;
insert into herramienta values ('R-04', 'Recuperar', 'Microsoft OneDrive', 'ambos', 'https://go.microsoft.com/fwlink/p/?LinkId=259455', 'microsoft.com', 'Gratis 5 GB; bajo costo 19,99 USD/año en EE. UU. (100 GB)', true, 5, 'Respalda en la nube Escritorio, Documentos e Imágenes y conserva versiones anteriores. Vía más directa para el computador con Windows que ya tiene cuenta Microsoft. Los archivos borrados pueden restaurarse desde la papelera de OneDrive.', 'PR.DS-11 / RC.RP-03', 'Primera opción (nube en Windows)') on conflict (id) do nothing;
insert into herramienta values ('R-03', 'Recuperar', 'Google Drive para computadoras', 'ambos', 'https://www.google.com/drive/download/', 'google.com', 'Gratis (15 GB compartidos)', true, 4, 'Sincroniza carpetas del computador con la nube. Si el equipo se daña o lo roban, los archivos se recuperan desde cualquier dispositivo con la cuenta de Google. Los archivos borrados pueden restaurarse desde la papelera de Google Drive.', 'PR.DS-11 / RC.RP-03', 'Primera opción (nube con cuenta Google)') on conflict (id) do nothing;
insert into herramienta values ('R-06', 'Recuperar', 'Copia de seguridad de Google One (Android)', 'celular', 'https://play.google.com/store/apps/details?id=com.google.android.apps.subscriptions.red', 'google.com', 'Gratis (15 GB compartidos)', true, 5, 'Guarda en la cuenta de Google los datos y ajustes del teléfono para restaurarlos en un equipo nuevo. Reduce el tiempo para volver a operar si se pierde el celular con el que se cobra.', 'PR.DS-11 / RC.RP-03', 'Primera opción (celular Android)') on conflict (id) do nothing;
insert into herramienta values ('R-07', 'Recuperar', 'Copia de seguridad de iCloud (iPhone)', 'celular', 'https://help.apple.com/icloud/es.lproj/mmab848634c8.html', 'apple.com', 'Gratis (usa el espacio de iCloud)', true, 5, 'Respalda el iPhone una vez al día con Wi-Fi, bloqueado y cargando. Apple puede borrar copias con más de 180 días sin actualizarse.', 'PR.DS-11 / RC.RP-03', 'Primera opción (iPhone)') on conflict (id) do nothing;
insert into herramienta values ('R-05', 'Recuperar', 'Copia de seguridad de WhatsApp', 'celular', 'https://faq.whatsapp.com/481135090640375/?locale=es_ES&cms_platform=android', 'whatsapp.com', 'Gratis (usa el espacio de Google o iCloud)', true, 5, 'Guarda los chats con frecuencia diaria, semanal o mensual y permite cifrar la copia de extremo a extremo. Al cambiar o perder el celular se recuperan pedidos, contactos y conversaciones con clientes.', 'PR.DS-11 / RC.RP-03', 'Primera opción (chats de WhatsApp)') on conflict (id) do nothing;
insert into herramienta values ('R-18', 'Recuperar', 'Google Fotos – Copia de seguridad', 'celular', 'https://play.google.com/store/apps/details?id=com.google.android.apps.photos', 'google.com', 'Gratis (15 GB compartidos)', true, 5, 'Guarda automáticamente en la nube las fotos y videos del celular; también puede respaldar la carpeta de imágenes de WhatsApp, que viene desactivada por defecto. Si se pierde el celular, el negocio conserva las fotos de productos, comprobantes y facturas.', 'PR.DS-11 / RC.RP-03', 'Primera opción (fotos del celular)') on conflict (id) do nothing;
